import{_ as i,o as a,c as r,a2 as t}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"Documentazione di Clarae notanda","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),l={name:"index.md"};function o(n,e,d,s,c,u){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="documentazione-di-clarae-notanda" tabindex="-1">Documentazione di Clarae notanda <a class="header-anchor" href="#documentazione-di-clarae-notanda" aria-label="Permalink to &quot;Documentazione di Clarae notanda&quot;">​</a></h1><p><strong>Clarae notanda</strong> è un&#39;app di knowledge management <em>local-first</em>. Le note sono file ordinari (<code>.md</code>, <code>.canvas</code>, <code>.base</code>, <code>.excalidraw</code>) in una cartella, il <em>vault</em>, apribile anche da altri editor: l&#39;app funziona completamente offline e il cloud è facoltativo.</p><ul><li><strong>Client desktop</strong> (macOS, Windows, Linux) su Wails v3, Go e React/TypeScript: editor Markdown, link e backlink, grafo, ricerca full-text, lavagne, disegni Excalidraw, basi, presentazioni, applicazioni web e terminale integrato.</li><li><strong>Cloud Service</strong> self-hosted in Go (PostgreSQL, storage S3-compatibile, autenticazione Keycloak/OIDC) per sincronizzare i vault tra dispositivi e condividerli con utenti e gruppi. Il merge avviene sempre sul client: il server ordina le modifiche e archivia i contenuti senza interpretarli.</li><li><strong>Due tipi di vault cloud</strong>, scelti alla creazione: <em>privati</em>, cifrati end-to-end sul client e non condivisibili, e <em>condivisi</em>, collaborativi e con la presenza in tempo reale degli altri utenti.</li><li><strong>Web UI</strong> incorporata nel binario del cloud: console utente e di amministrazione, e il workbench del vault nel browser, con la stessa interfaccia del desktop sul core Go compilato in WebAssembly.</li></ul><p>Questa pagina è il punto d&#39;ingresso alla documentazione del repository; la versione corrente è descritta nel <a href="https://github.com/E2BRAdvisory/Clarae/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG</a>.</p><h2 id="fonti-di-verita" tabindex="-1">Fonti di verità <a class="header-anchor" href="#fonti-di-verita" aria-label="Permalink to &quot;Fonti di verità&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Documento</th><th>Contenuto</th></tr></thead><tbody><tr><td><a href="https://github.com/E2BRAdvisory/Clarae/blob/main/Specifications.md" target="_blank" rel="noreferrer">Specifications.md</a></td><td>Specifica (v1.9): architettura, vincoli V-xx, decisioni D-xx, schema del database, API, protocollo di sync</td></tr><tr><td><a href="./adr/">ADR</a></td><td>Deviazioni e precisazioni rispetto allo spec, con il loro stato</td></tr><tr><td><a href="./roadmap.html">Roadmap</a></td><td>Piano di sviluppo per milestone, con work package, ordine e criteri di uscita</td></tr><tr><td><a href="https://github.com/E2BRAdvisory/Clarae/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG</a></td><td>Note di rilascio di ogni versione</td></tr><tr><td><a href="https://github.com/E2BRAdvisory/Clarae/blob/main/README.md" target="_blank" rel="noreferrer">README</a></td><td>Presentazione, installazione rapida e ambiente di sviluppo</td></tr><tr><td><a href="https://github.com/E2BRAdvisory/Clarae/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING</a></td><td>Regole per contribuire</td></tr></tbody></table><h2 id="da-dove-cominciare" tabindex="-1">Da dove cominciare <a class="header-anchor" href="#da-dove-cominciare" aria-label="Permalink to &quot;Da dove cominciare&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chi</th><th>Da leggere</th></tr></thead><tbody><tr><td>Chi usa l&#39;app</td><td><a href="./user-guide/">Guida utente</a></td></tr><tr><td>Chi installa e gestisce il cloud</td><td><a href="./admin-guide/">Guida dell&#39;amministratore</a></td></tr><tr><td>Chi sviluppa</td><td><a href="./dev-setup.html">Ambiente di sviluppo</a>, <a href="./architecture.html">Architettura</a>, <a href="./desktop-web-sync.html">Desktop e web allineati</a></td></tr></tbody></table><h2 id="guida-utente" tabindex="-1">Guida utente <a class="header-anchor" href="#guida-utente" aria-label="Permalink to &quot;Guida utente&quot;">​</a></h2><p>Indice della guida: <a href="./user-guide/">user-guide/README.md</a>.</p><ul><li><a href="./user-guide/installazione.html">Installazione</a>: requisiti e passi per macOS, Windows e Linux, aggiornamento dalle versioni 1.x.</li><li><a href="./user-guide/primo-vault.html">Il primo vault</a>: creare o aprire un vault e orientarsi nell&#39;interfaccia.</li><li><a href="./user-guide/scrivere-link-proprieta.html">Scrivere, link e proprietà</a>: editor, modalità Live, Sorgente e Lettura, link interni, proprietà.</li><li><a href="./user-guide/template-note-giornaliere.html">Template e note giornaliere</a>: modelli di nota e note del giorno.</li><li><a href="./user-guide/ricerca.html">Ricerca</a>: ricerca full-text e operatori.</li><li><a href="./user-guide/canvas-disegni-bases-grafo.html">Lavagne, disegni, basi e grafo</a>: file <code>.canvas</code>, disegni Excalidraw, <code>.base</code>, grafo 2D e 3D.</li><li><a href="./user-guide/presentazioni.html">Presentazioni</a>: presentare una nota Markdown o slide curate.</li><li><a href="./user-guide/applicazioni.html">Applicazioni</a>: pagine web registrate nel vault e aperte in una scheda.</li><li><a href="./user-guide/terminale.html">Terminale</a>: il terminale integrato del client desktop.</li><li><a href="./user-guide/sync-cloud.html">Sincronizzazione e cloud</a>: collegare il cloud e sincronizzare i vault.</li><li><a href="./user-guide/vault-privati-condivisi.html">Vault privati e condivisi</a>: cifratura end-to-end, passphrase e recovery key.</li><li><a href="./user-guide/condivisione-gruppi.html">Condivisione e gruppi</a>: condividere vault, cartelle e documenti.</li><li><a href="./user-guide/presenza.html">Presenza</a>: chi altro ha aperto lo stesso documento in un vault condiviso.</li><li><a href="./user-guide/cronologia-recupero.html">Cronologia e recupero</a>: snapshot locali, storico delle versioni e copie di conflitto.</li><li><a href="./user-guide/import-export.html">Importare ed esportare</a>: importazione guidata da altre app ed esportazione.</li><li><a href="./user-guide/impostazioni-scorciatoie.html">Impostazioni e scorciatoie</a>: impostazioni per vault e scorciatoie da tastiera.</li><li><a href="./user-guide/accessibilita.html">Accessibilità</a>: stato dei controlli di accessibilità.</li><li><a href="./user-guide/risoluzione-problemi.html">Risoluzione dei problemi</a>: problemi frequenti e rimedi.</li></ul><h2 id="guida-dell-amministratore" tabindex="-1">Guida dell&#39;amministratore <a class="header-anchor" href="#guida-dell-amministratore" aria-label="Permalink to &quot;Guida dell&#39;amministratore&quot;">​</a></h2><p>Indice della guida: <a href="./admin-guide/">admin-guide/README.md</a>.</p><ul><li><a href="./admin-guide/installazione.html">Installazione</a>: componenti, Helm su Kubernetes, Docker Compose, segreti e verifica.</li><li><a href="./admin-guide/configurazione.html">Riferimento di configurazione</a>: tutte le variabili d&#39;ambiente di <code>clarae-cloud</code> e il flag <code>--role</code>.</li><li><a href="./admin-guide/keycloak.html">Keycloak</a>: realm, client OIDC e validazione dei token.</li><li><a href="./admin-guide/profili-quote-audit.html">Config profile, quote, limiti e audit</a>: governance dalla console di amministrazione.</li><li><a href="./admin-guide/presenza.html">Presenza in tempo reale</a>: il canale WebSocket della presenza e come esporlo.</li><li><a href="./admin-guide/monitoraggio.html">Monitoraggio e osservabilità</a>: endpoint di salute, metriche, log e tracce.</li><li><a href="./admin-guide/backup-upgrade.html">Backup, ripristino e upgrade</a>: principi e comandi essenziali.</li><li><a href="./admin-guide/runbook.html">Runbook degli incidenti</a>: sintomo, verifica, rimedio.</li><li><a href="./admin-guide/migrazione-clarae.html">Migrazione a Clarae notanda</a>: aggiornare un&#39;installazione fatta con le versioni 1.x.</li><li><a href="./runbook/backup-restore.html">Runbook di backup e restore</a>: procedure dettagliate per PostgreSQL e bucket S3, con RPO e RTO misurati.</li></ul><h2 id="sviluppo-e-architettura" tabindex="-1">Sviluppo e architettura <a class="header-anchor" href="#sviluppo-e-architettura" aria-label="Permalink to &quot;Sviluppo e architettura&quot;">​</a></h2><ul><li><a href="./dev-setup.html">Ambiente di sviluppo</a>: prerequisiti, task, stack locale, avvio di cloud e desktop.</li><li><a href="./architecture.html">Architettura</a>: panoramica del codice per chi inizia.</li><li><a href="./desktop-web-sync.html">Desktop e web allineati</a>: come si aggiunge una funzione con la parità desktop/workbench/console per costruzione.</li><li><a href="./web-ui.html">Web UI</a>: console utente e di amministrazione e host del workbench.</li><li><a href="./web-workbench-parity.html">Parità tra il workbench web e il client desktop</a>: stato funzione per funzione (tabelle generate da <code>scripts/parity.mjs</code>).</li><li><a href="./qa/i18n-glossary.html">Glossario e linee guida per la traduzione</a>: terminologia italiana e regole delle stringhe it/en.</li></ul><h2 id="decisioni-architetturali-adr" tabindex="-1">Decisioni architetturali (ADR) <a class="header-anchor" href="#decisioni-architetturali-adr" aria-label="Permalink to &quot;Decisioni architetturali (ADR)&quot;">​</a></h2><p>L&#39;elenco completo, con lo stato di ogni decisione, è in <a href="./adr/">adr/README.md</a>; i nuovi ADR partono dal <a href="./adr/0000-template.html">template</a>. Alcuni dei più strutturali:</p><ul><li><a href="./adr/0029-web-workbench.html">ADR-0029</a> e <a href="./adr/0030-desktop-core-wasm.html">ADR-0030</a>: workbench del vault nella Web UI e core Go in WebAssembly.</li><li><a href="./adr/0037-registro-funzioni-e-cloud-features.html">ADR-0037</a> e <a href="./adr/0045-parita-per-costruzione.html">ADR-0045</a>: parità desktop/web per costruzione.</li><li><a href="./adr/0051-wails-v3.html">ADR-0051</a>: migrazione a Wails v3.</li><li><a href="./adr/0052-rebrand-clarae-notanda.html">ADR-0052</a>: il nome «Clarae notanda».</li><li><a href="./adr/0064-terminale-integrato-e-finestra-separata.html">ADR-0064</a>: terminale integrato.</li><li><a href="./adr/0065-presenza-in-tempo-reale.html">ADR-0065</a>: presenza in tempo reale sui vault condivisi.</li></ul><h2 id="sicurezza" tabindex="-1">Sicurezza <a class="header-anchor" href="#sicurezza" aria-label="Permalink to &quot;Sicurezza&quot;">​</a></h2><ul><li><a href="./security/crypto-design.html">Design crittografico dei vault privati</a>: pacchetto per la revisione esterna della cifratura end-to-end.</li><li><a href="./security/data-retention.html">Conservazione dei dati e cancellazione GDPR</a>: durata di ogni classe di dato e cancellazione dell&#39;account.</li><li><a href="./security/pentest-scope.html">Preparazione al penetration test</a>: perimetro, regole e modello di report.</li></ul><h2 id="qualita-e-verifica-manuale" tabindex="-1">Qualità e verifica manuale <a class="header-anchor" href="#qualita-e-verifica-manuale" aria-label="Permalink to &quot;Qualità e verifica manuale&quot;">​</a></h2><p>Accessibilità:</p><ul><li><a href="./qa/a11y-desktop.html">Client desktop</a>: copertura automatica e checklist manuale.</li><li><a href="./qa/a11y-web.html">Web UI</a>: copertura automatica e checklist manuale.</li></ul><p>Checklist e runbook di verifica per milestone:</p><ul><li><a href="./qa/m0-checklist.html">M0 — «Hello vault» con login</a></li><li><a href="./qa/parita-funzionale-m1.html">M1 — Parità funzionale</a></li><li><a href="./qa/m3-drawings-canvas.html">M3 — Disegni e canvas</a></li><li><a href="./qa/m4-sharing.html">M4 — Condivisione, gruppi e configurazione</a></li><li><a href="./qa/m5-admin-export.html">M5 — Console admin ed export</a></li><li><a href="./qa/m6-search-export.html">M6 — Ricerca incorporata, export, impostazioni</a></li><li><a href="./qa/m8-shell-ui.html">M8 — Revisione della shell desktop</a></li><li><a href="./qa/m15-wails3-matrice.html">M15 — Client desktop su Wails v3</a></li><li><a href="./qa/m18-webview-matrice.html">M18 — Applicazioni in una vista nativa</a></li><li><a href="./qa/verifica-manuale-1.7.html">Versione 1.7 — Prove sulla finestra reale</a></li><li><a href="./qa/m21-correttivi.html">M21 — Correttivi dello schizzo del 2026-11-15</a></li><li><a href="./qa/m22-nomi-file-e-applicazioni.html">M22 — Nomi dei file senza estensione e applicazioni su Windows e Linux</a></li><li><a href="./qa/m23-terminale.html">M23 — Terminale integrato e finestra separata</a></li><li><a href="./qa/m25-presenza.html">M25 — Presenza in tempo reale</a></li></ul><p>Benchmark:</p><ul><li><a href="./qa/m6-graph-benchmark.html">Graph view (M6)</a>: grafo 2D da 10k nodi.</li><li><a href="./qa/graph-3d-benchmark.html">Grafo 3D (M18)</a> e le <a href="./qa/graph-3d-spike-d0/">misure grezze dello spike</a>.</li></ul><h2 id="prestazioni" tabindex="-1">Prestazioni <a class="header-anchor" href="#prestazioni" aria-label="Permalink to &quot;Prestazioni&quot;">​</a></h2><ul><li><a href="./perf/">Prestazioni</a>: obiettivi dell&#39;Appendice A dello spec, misure e come ripeterle.</li><li><a href="./perf/wasm-spike.html">Spike del core WASM</a>: misure alla base di ADR-0030.</li></ul><h2 id="rilascio" tabindex="-1">Rilascio <a class="header-anchor" href="#rilascio" aria-label="Permalink to &quot;Rilascio&quot;">​</a></h2><ul><li><a href="./release/">Processo di rilascio</a>: <code>release.yml</code>, artefatti pubblicati e verifiche prima del tag.</li><li><a href="./release/secrets.html">Segreti e variabili della pipeline</a>: cosa usa la pipeline di rilascio.</li><li><a href="./release/v1.0.0-checklist.html">Checklist di rilascio 1.0.0</a>: storica.</li><li><a href="./release/rebrand-inventory.html">Inventario del rebrand</a>: storico del primo cambio di nome, prima della 1.0.</li></ul><h2 id="proposte-di-aggiornamento-dello-spec" tabindex="-1">Proposte di aggiornamento dello spec <a class="header-anchor" href="#proposte-di-aggiornamento-dello-spec" aria-label="Permalink to &quot;Proposte di aggiornamento dello spec&quot;">​</a></h2><p>Documenti storici: ciascuno ha preparato una versione di <code>Specifications.md</code>, poi recepita dall&#39;owner.</p><ul><li><a href="./spec-v1.2-proposta.html">v1.2</a></li><li><a href="./spec-v1.7-proposta.html">v1.7</a></li><li><a href="./spec-v1.8-proposta.html">v1.8</a></li><li><a href="./spec-v1.9-proposta.html">v1.9</a></li></ul>',35)])])}const p=i(l,[["render",o]]);export{m as __pageData,p as default};
